'@
New-Item -ItemType Directory -Force -Path $release|Out-Null
foreach($m in $members){$dst=Join-Path $release $m.path;New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($dst))|Out-Null;[IO.File]::WriteAllBytes($dst,[Convert]::FromBase64String($m.base64));$h=(Get-FileHash $dst -Algorithm SHA256).Hash.ToLower();if($h -ne $m.sha256){throw "MEMBER_HASH_MISMATCH $($m.path)"}}
$smoke=Join-Path $release 'automation-c-v1/rc5_full_smoke.cjs'
& node $smoke $release
if($LASTEXITCODE -ne 0){throw 'SMOKE_FAILED'}
$launcherBackup="$ExistingLauncherPath.pre-rc5"
Copy-Item $ExistingLauncherPath $launcherBackup -Force
Set-Content -Encoding ASCII -Path $ExistingLauncherPath -Value ("@echo off`r`nset YOLLA_RELEASE_ROOT=$release`r`n")
$post=@{}
foreach($p in $pre.Keys){$x=Join-Path $ExistingStateRoot $p;$post[$p]=@{exists=Test-Path $x;hash=if(Test-Path $x -PathType Leaf){(Get-FileHash $x -Algorithm SHA256).Hash.ToLower()}else{$null}};if($pre[$p].exists -ne $post[$p].exists -or $pre[$p].hash -ne $post[$p].hash){Copy-Item $launcherBackup $ExistingLauncherPath -Force;Remove-Item $release -Recurse -Force;throw "PRESERVATION_FAILED $p"}}
[ordered]@{version=$target;release=$release;member_count=$members.Count;smoke='PASS';launcher_switched=$true;install_time_network_dependency=$false;legacy_a_e_reintroduction_count=0;pre=$pre;post=$post}|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 (Join-Path $release 'INSTALL_RECEIPT.json')
